class TrieNode:
    def __init__(self):
        self.children = {}
        self.pseudonyms = []  # Indices of pseudonyms passing through this node

class Solution:
    def solve(self, n, students, pseudonyms):
        # Build a trie of pseudonyms
        trie = [TrieNode()]

        for idx, name in enumerate(pseudonyms):
            node = trie[0]
            for char in name:
                if char not in node.children:
                    node.children[char] = TrieNode()
                    trie.append(node.children[char])
                node = node.children[char]
            node.pseudonyms.append(idx)

        # Compute LCP for each student with relevant pseudonyms
        def get_lcp(s1, s2):
            i = 0
            while i < min(len(s1), len(s2)) and s1[i] == s2[i]:
                i += 1
            return i

        # Store (lcp, student_idx, pseudonym_idx) as (negated for max heap)
        pairs = []
        for i, student in enumerate(students):
            node = trie[0]
            j = 0
            for char in student:
                if char in node.children:
                    node = node.children[char]
                    j += 1
                else:
                    break
            for pid in node.pseudonyms:
                lcp = j
                pairs.append((-lcp, i, pid))  # negative lcp for max heap

        # Sort pairs by LCP (descending)
        pairs.sort()

        # Greedy assignment
        assigned_pseudonym = [-1] * n
        assigned_student = [-1] * n
        total_quality = 0

        for lcp, s_idx, p_idx in pairs:
            if assigned_pseudonym[p_idx] == -1 and assigned_student[s_idx] == -1:
                assigned_pseudonym[p_idx] = s_idx
                assigned_student[s_idx] = p_idx
                total_quality += -lcp

        # Output
        result = [str(total_quality)]
        for i in range(n):
            result.append(f"{assigned_student[i] + 1} {assigned_pseudonym[assigned_student[i]] + 1}")

        return '\n'.join(result)

    def compute_total_lcp(subtree_nodes):
        score = 0
        for node in subtree_nodes:
            if node:
                if node.pseudonyms:
                    score += len(node.pseudonyms)
        return score

