import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[1 + i].split()))
        e, a, b = parts[0], parts[1], parts[2]
        edges.append((e, a, b, i))

    # If graph has no edges (m = n-1 means exactly spanning tree, output nothing)
    if m == n - 1:
        return ""

    # Kruskal's algorithm to build MST
    sorted_edges = sorted(edges, key=lambda x: x[0])

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_adj = [[] for _ in range(n + 1)]
    mst_edge_count = 0
    mst_indices = set()

    for e, a, b, idx in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_indices.add(idx)
            mst_edge_count += 1
            if mst_edge_count == n - 1:
                break

    # Binary lifting for LCA and max edge on path
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_weight = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)

    # BFS to set up depth and immediate parent
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    depth[1] = 0

    while queue:
        u = queue.pop(0)
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                up[0][v] = u
                max_weight[0][v] = w
                queue.append(v)

    # Build binary lifting tables
    for j in range(1, LOG):
        for i in range(1, n + 1):
            up[j][i] = up[j - 1][up[j - 1][i]]
            max_weight[j][i] = max(max_weight[j - 1][i], max_weight[j - 1][up[j - 1][i]])

    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        for j in range(LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                res = max(res, max_weight[j][u])
                u = up[j][u]

        if u == v:
            return res

        for j in range(LOG - 1, -1, -1):
            if up[j][u] != up[j][v]:
                res = max(res, max_weight[j][u])
                res = max(res, max_weight[j][v])
                u = up[j][u]
                v = up[j][v]

        res = max(res, max_weight[0][u])
        res = max(res, max_weight[0][v])
        return res

    result = []
    for e, a, b, idx in edges:
        if idx not in mst_indices:
            result.append(str(query_max(a, b)))

    return '\n'.join(result)

