import random

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        coords = list(map(float, lines[i].split()))
        points.append(coords)

    if n == 0:
        return "0.000000 0.000000 0.000000\n"

    def dist(p1, p2):
        return math.sqrt((p1[0]-p2[0])**2 + **(p1[1]-p2[1])2 + (p1[2]-p2[2])**2)

    def max_dist(p, pts):
        return max(dist(p, pt) for pt in pts)

    # Try centroid
    centroid = [sum(p[i] for p in points) / n for i in range(3)]
    best_pt = centroid[:]
    best_val = max_dist(centroid, points)

    # Try all pairs (midpoint as diameter candidates)
    for i in range(n):
        for j in range(i + 1, n):
            mid = [(points[i][k] + points[j][k]) / 2 for k in range(3)]
            cur = max_dist(mid, points)
            if cur < best_val:
                best_val = cur
                best_pt = mid[:]

    # Try randomized search for better results
    best_pt = [
        sum(p[i] for p in points) / n + random.uniform(-0.1, 0.1) for i in range(3)
    ]
    best_val = max_dist(best_pt, points)

    for _ in range(1000):
        for _ in range(50):
            cand = [best_pt[k] + random.uniform(-0.01, 0.01) for k in range(3)]
            cur = max_dist(cand, points)
            if cur < best_val - 1e-9:
                best_val = cur
                best_pt = cand[:]

    return "{:.12f} {:.12f} {:.12f}\n".format(best_pt[0], best_pt[1], best_pt[2])

