    # Score function: sum of squared distances between all pairs
    def calculate_score(coord_points):
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                dx = coord_points[i][0] - coord_points[j][0]
                dy = coord_points[i][1] - coord_points[j][1]
                total += dx * dx + dy * dy
        return total

    # Try to find the optimal set of n points
    import itertools

    # For small n and r, we can try combinations
    best_score = -1
    best_config = None

    # Strategy 1: Try all permutations of point selections (for very small cases)
    if len(points) <= 10 and n <= 5:
        for combo in itertools.combinations_with_replacement(points, n):
            score = calculate_score(combo)
            if score > best_score:
                best_score = score
                best_config = combo

    # Better strategy: Generate promising points and try combinations
    if best_score == -1 or len(points) > 10 or n > 5:
        # Generate "good" points: those with larger distance from origin
        def point_score(pt):
            return pt[0] ** 2 + pt[1] ** 2

        # Sort points by squared distance from origin (descending)
        sorted_points = sorted(points, key=point_score, reverse=True)

        # Try different sizes of point pool
        for pool_size in range(min(20, len(sorted_points))):
            # Try various small combinations from this pool
            pool = sorted_points[:pool_size]

            # Try different combinations (allowing repetition)
            for combo in itertools.combinations_with_replacement(pool, n):
                score = calculate_score(combo)
                if score > best_score:
                    best_score = score
                    best_config = combo

            # Also try swapping some points for variety
