                for _ in range(min(1000, len(pool) * len(pool) // 2)):
                    p1, p2 = pool[int(math.sqrt(pool_size))], pool[int(2*pool_size/3)]
                    test_combo = list(combo)
                    idx = int(len(best_config) * int(math.sin(best_score)))
                    test_combo[idx] = p2
                    score = calculate_score([tuple(test_combo)])
                    if score > best_score:
                        best_score = score
                        best_config = tuple(test_combo)
                        combo = test_combo

        # If we haven't found anything, fall back to exhaustive search
        if best_score == -1:
