        for i in range(n):
            matrix.append(list(map(int, lines[line_idx].split())))
            line_idx += 1

        ops = lines[line_idx]
        line_idx += 1

        for op in ops:
            if op == 'R':
                # Cyclically shift all columns to the right
                matrix = [row[-1:] + row[:-1] for row in matrix]
            elif op == 'L':
                # Cyclically shift all columns to the left
                matrix = [row[1:] + row[:1] for row in matrix]
            elif op == 'D':
                # Cyclically shift all rows down (row 0 gets last row)
                matrix = [matrix[-1]] + matrix[:-1]
            elif op == 'U':
                # Cyclically shift all rows up (row 0 gets row 1)
                matrix = matrix[1:] + [matrix[0]]
            elif op == 'I':
                # Replace each row with its inverse permutation
                new_matrix = []
                for row in matrix:
                    inv = [0] * (n + 1)
                    for j, val in enumerate(row):
                        inv[val] = j + 1  # inv[value] = position
                    inv_row = [inv[j] for j in range(n)]
                    new_matrix.append(inv_row)
                matrix = new_matrix
            elif op == 'C':
                # Replace each column with its inverse permutation
                new_matrix = [[0] * n for _ in range(n)]
                for j in range(n):
                    col = [matrix[i][j] for i in range(n)]
                    inv = [0] * (n + 1)
                    for i, val in enumerate(col):
                        inv[val] = i + 1  # inv[value] = row position
                    for i in range(n):
                        new_matrix[i][j] = inv[i]
                matrix = new_matrix

        output_lines = []
        for row in matrix:
            output_lines.append(' '.join(map(str, row)) + ' ')
        results.append('\n'.join(output_lines))

    return '\n'.join(results)

import math

def solution(input_str):
    n, l, r = map(int, input_str.strip().split())

    # Handle n=1: any single number in [l, r]
    if n == 1:
        return str(r - l + 1)

    # Handle n=2: any pair of distinct numbers
    if n == 2:
        return str((r - l + 1) * (r - l))

    count = 0

    # Maximum value we need to consider for a and b
    max_val = int(r**(1/(n - 1)) + 2)

    # Count increasing progressions (a < b, ratio = b/a > 1)
    # Terms: k*a^(n-1), k*a^(n-2)*b, ..., k*b^(n-1)
    # min = k*a^(n-1), max = k*b^(n-1)
    # Need: l <= k*a^(n-1) and k*b^(n-1) <= r
    for a in range(1, max_val):
        for b in range(a + 1, max_val):
            if math.gcd(a, b) != 1:
                continue

            a_pow = a**(n - 1)
            b_pow = b**(n - 1)

            # If b_pow > r, then all higher b will also exceed r
            if b_pow > r:
                break

            min_k = (l + a_pow - 1) // a_pow
            max_k = r // b_pow

            if min_k <= max_k:
                count += max_k - min_k + 1

    # Count decreasing progressions (a > b, ratio = b/a < 1)
    # Terms: same formula, but a > b
    # min = k*b^(n-1), max = k*a^(n-1)
    # Need: l <= k*b^(n-1) and k*a^(n-1) <= r
    for b in range(1, max_val):
        for a in range(b + 1, max_val):
            if math.gcd(a, b) != 1:
                continue

            a_pow = a**(n - 1)
            b_pow = b**(n - 1)

            # If a_pow > r, then all higher a will also exceed r
            if a_pow > r:
                break

            min_k = (l + b_pow - 1) // b_pow
            max_k = r // a_pow

            if min_k <= max_k:
                count += max_k - min_k + 1

    return str(count)

def is_bitonic(arr):
    """Check if array is bitonic - increases then decreases."""
    if len(arr) <= 1:
        return True
    peak_idx = 0
    for k in range(1, len(arr)):
        if arr[k] > arr[peak_idx]:
            peak_idx = k
        else:
            if peak_idx == 0:
                peak_idx = k
                break
            if arr[k] <= arr[peak_idx - 1]:
                # Already started decreasing or invalid
                pass

    # Check that after peak, values keep decreasing
    if len(arr) > peak_idx + 1:
        for k in range(peak_idx + 1, len(arr)):
            if arr[k] >= arr[k - 1]:
                return False

    return True


