# Initial test: count inversions in a permutation using Binary Indexed Tree (BIT)
# The permutation is modified by swaps, and we need to output inversion count after each swap

class FenwickTree:
    def __init__(self, n):
        self.tree = [0] * (n + 1)

    def update(self, i, delta=1):
        while i < len(self.tree):
            self.tree[i] += delta
            i += i & (-i)

    def query(self, i):
        result = 0
        while i > 0:
            result += self.tree[i]
            i -= i & (-i)
        return result


