        if l == r:
            output.append(str(0))
        else:
            a[l - 1], a[r - 1] = a[r - 1], a[l - 1]

            # Count inversions using BIT
            # An inversion is a pair (i, j) with i < j and a[i] > a[j]
            # Process from right to left, count how many smaller elements seen so far
            bit = FenwickTree(n)
            inversions = 0

            for val in reversed(a):
                inversions += bit.query(val - 1)
                bit.update(val, 1)

            output.append(str(inversions))

    return '\n'.join(output)


