import sys

def is_prime_mr(n):
    """Miller-Rabin primality test"""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Witnesses for n < 4,759,123,141
    if n < 4759123141:
        witnesses = [2, 7, 61]
    elif n < 1122004669633:
        witnesses = [2, 13, 23, 1662803]
    else:
        witnesses = [2, 3, 5, 7, 11, 13, 17, 19, 23]

    for a in witnesses:
        if a >= n:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def multiplicative_order(a, p):
    """Computes the multiplicative order of a modulo p"""
    if a % p == 0:
        return p - 1

    phi = p - 1

    # Find all divisors of phi
    divs = [1]
    i = 2
    temp = phi
    while i * i <= temp:
        if temp % i == 0:
            divs.append(i)
            while temp % i == 0:
                temp //= i
        i += 1
    if temp > 1:
        divs.append(temp)

    # Sort and find smallest d where a^d ≡ 1 (mod p)
    divs = sorted(set(divs))
    for d in divs:
        if pow(a, d, p) == 1:
            return d
    return phi

